def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]

    walls = [r for r, row in enumerate(grid) if all(x == 2 for x in row)]
    wall = walls[0] if walls else None

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                out[r][c] = 2
            elif grid[r][c] == 4 and r + 1 < h:
                nr = r + 1
                out[nr][c] = 4

                # A 4 landing just above the barrier sends diagonal rays upward.
                if wall is not None and nr == wall - 1:
                    for dc in (-1, 1):
                        rr, cc = nr, c
                        while rr > 0:
                            rr -= 1
                            cc += dc
                            if 0 <= cc < w:
                                out[rr][cc] = 4
                            else:
                                break

    return out
